import java.io.*;
class SubmissionStorageException extends Exception{SubmissionStorageException(String m,Throwable c){super(m,c);}} class Storage {static void save(String file)throws SubmissionStorageException{try{if(file.contains("bad"))throw new IOException("Disk quota exceeded");System.out.println("Saved "+file);}catch(IOException e){throw new SubmissionStorageException("Could not store "+file,e);}}} public class Main {public static void main(String[]a){for(String f:new String[]{"answer01.pdf","bad-answer02.pdf"})try{Storage.save(f);}catch(SubmissionStorageException e){System.out.println("Error: "+e.getMessage());System.out.println("Cause: "+e.getCause().getMessage());}}}
